contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        uint256 beforeBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeRemaining = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 currentValue = c.value(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.getTokens{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterRemaining = c.totalRemaining(); if (__ESBMC_reverted()) return;

        assert(!reverted ? (afterBalance == beforeBalance + currentValue && afterRemaining == beforeRemaining - currentValue) : (afterBalance == beforeBalance && afterRemaining == beforeRemaining));
    }

    receive() external payable {}
}

