pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeBalance;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        uint256 beforeRemaining;
        try c.totalRemaining() returns (uint256 __r) { beforeRemaining = __r; } catch { return; }
        uint256 currentValue;
        try c.value() returns (uint256 __r) { currentValue = __r; } catch { return; }
        bool reverted;
        try c.getTokens{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBalance;
        try c.balanceOf(address(this)) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        uint256 afterRemaining;
        try c.totalRemaining() returns (uint256 __r) { afterRemaining = __r; } catch { return; }
        assertTrue(!reverted ? (afterBalance == beforeBalance + currentValue && afterRemaining == beforeRemaining - currentValue) : (afterBalance == beforeBalance && afterRemaining == beforeRemaining));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
